#!/usr/bin/env python3
"""Publish the existing Delimt APK and prepare its website update. No APK build."""
import argparse
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import struct
import subprocess
import sys
import tempfile
import time
from urllib.error import HTTPError
from urllib.parse import urlparse
from urllib.request import Request, urlopen
import zipfile
import zlib

PAYLOAD = json.loads(zlib.decompress(base64.b64decode("")))
REPOSITORY = "activist015/delimt"
BUILD_ID = "0beb0151-e8fa-454b-8c18-9044b82b01d5"
BUILD_PAGE = "https://expo.dev/accounts/delimt/projects/delimt-android/builds/" + BUILD_ID
TAG = "android-0beb0151"
APK_NAME = "delimt-android.apk"
DOWNLOAD_URL = "https://github.com/activist015/delimt/releases/download/" + TAG + "/" + APK_NAME
CONFIG_PATH = "src/android-release.json"
EAS_PREFIX = ["npx", "--yes", "eas-cli@25.3.0"]
TITLE = "Add Android APK download and installation guide"


def run(args, cwd, *, capture=False, check=True):
    result = subprocess.run(args, cwd=cwd, text=True,
                            stdout=subprocess.PIPE if capture else None,
                            stderr=subprocess.PIPE if capture else None)
    if check and result.returncode:
        detail = (result.stderr or result.stdout or "").strip() if capture else ""
        raise RuntimeError("Command failed: " + " ".join(args[:4]) + ("\n" + detail if detail else ""))
    return result


def blob_hash(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()


def sha256_file(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def valid_config(data):
    return (data.get("buildId") == BUILD_ID and data.get("url") == DOWNLOAD_URL
            and isinstance(data.get("version"), str) and bool(data["version"].strip())
            and type(data.get("byteSize")) is int and data["byteSize"] > 0
            and re.fullmatch(r"[0-9a-f]{64}", data.get("sha256") or "") is not None)


def apply_files(checkout, payload):
    writes = []
    for relative, entry in payload.items():
        if Path(relative).is_absolute() or ".." in Path(relative).parts:
            raise RuntimeError("Unsafe update path")
        path = checkout / relative
        for parent in [path, *path.parents]:
            if parent == checkout.parent:
                break
            if parent.is_symlink():
                raise RuntimeError("Refusing a symbolic link: " + relative)
        if path.exists() and not path.is_file():
            raise RuntimeError("Expected a regular file: " + relative)
        current = path.read_bytes() if path.exists() else None
        desired = base64.b64decode(entry["content"])
        if current == desired:
            continue
        if relative == CONFIG_PATH and current is not None:
            try:
                if valid_config(json.loads(current)):
                    continue
            except (ValueError, TypeError):
                pass
        if (blob_hash(current) if current is not None else None) != entry["before"]:
            raise RuntimeError(relative + " has changed since review. No update files were changed.")
        writes.append((path, desired))
    for path, desired in writes:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as temp:
            temp.write(desired)
            temporary = Path(temp.name)
        os.replace(temporary, path)
    return len(writes)


def prepare_worktree(root):
    run(["git", "fetch", "origin", "main"], root)
    checkout = root.parent / "delimt-android-download"
    if checkout.exists():
        actual = Path(run(["git", "rev-parse", "--show-toplevel"], checkout, capture=True).stdout.strip())
        branch = run(["git", "branch", "--show-current"], checkout, capture=True).stdout.strip()
        if actual.resolve() != checkout.resolve() or not branch.startswith("launch/android-download-"):
            raise RuntimeError("The output folder contains other work. Nothing was overwritten.")
        def common(path):
            return Path(run(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], path, capture=True).stdout.strip()).resolve()
        if common(root) != common(checkout):
            raise RuntimeError("The output folder belongs to another repository.")
    else:
        branch = "launch/android-download-" + BUILD_ID[:8]
        run(["git", "worktree", "add", "-b", branch, str(checkout), "origin/main"], root)
    changed = run(["git", "diff", "--name-only", "HEAD"], checkout, capture=True).stdout.splitlines()
    untracked = run(["git", "ls-files", "--others", "--exclude-standard"], checkout, capture=True).stdout.splitlines()
    if any(name not in PAYLOAD for name in changed + untracked):
        raise RuntimeError("The separate website branch contains other changes. They were preserved.")
    apply_files(checkout, PAYLOAD)
    return checkout, branch


def manifest_elements(data):
    """Read Android binary XML's string pool and start-element attributes."""
    if len(data) < 8 or struct.unpack_from("<H", data)[0] != 3:
        raise RuntimeError("The APK does not contain a binary Android manifest.")
    strings, elements = [], []
    offset = struct.unpack_from("<H", data, 2)[0]
    while offset + 8 <= len(data):
        kind, header, size = struct.unpack_from("<HHI", data, offset)
        if size < header or size < 8 or offset + size > len(data):
            raise RuntimeError("The Android manifest is malformed.")
        if kind == 1:
            count, _, flags, start, _ = struct.unpack_from("<IIIII", data, offset + 8)
            for index in range(count):
                item = offset + start + struct.unpack_from("<I", data, offset + header + index * 4)[0]
                def length8(position):
                    value = data[position]
                    return (((value & 127) << 8) | data[position + 1], position + 2) if value & 128 else (value, position + 1)
                if flags & 256:
                    _, item = length8(item)
                    length, item = length8(item)
                    strings.append(data[item:item + length].decode("utf-8"))
                else:
                    length = struct.unpack_from("<H", data, item)[0]
                    item += 2
                    if length & 32768:
                        length = ((length & 32767) << 16) | struct.unpack_from("<H", data, item)[0]
                        item += 2
                    strings.append(data[item:item + length * 2].decode("utf-16le"))
        elif kind == 258:
            name = struct.unpack_from("<I", data, offset + 20)[0]
            start, attr_size, count = struct.unpack_from("<HHH", data, offset + 24)
            attributes = {}
            for index in range(count):
                item = offset + 16 + start + index * attr_size
                _, key, raw, _, _, value_type, value = struct.unpack_from("<IIIHBBI", data, item)
                decoded = strings[raw] if raw != 0xffffffff else (strings[value] if value_type == 3 else bool(value) if value_type == 18 else value)
                attributes[strings[key]] = decoded
            elements.append((strings[name], attributes))
        offset += size
    return elements


def inspect_apk(apk, build):
    with zipfile.ZipFile(apk) as bundle:
        if "assets/index.android.bundle" not in bundle.namelist():
            raise RuntimeError("This APK has no bundled app code. Use the tested standalone build.")
        elements = manifest_elements(bundle.read("AndroidManifest.xml"))
    manifest = next((attrs for name, attrs in elements if name == "manifest"), {})
    application = next((attrs for name, attrs in elements if name == "application"), {})
    if manifest.get("package") != "com.delimt.app":
        raise RuntimeError("This APK belongs to a different Android package.")
    if application.get("debuggable", False):
        raise RuntimeError("This is a debuggable APK. Use the tested standalone release.")
    if not any(name == "service" and str(attrs.get("name", "")).endswith(".DelimtAccessibilityService") for name, attrs in elements):
        raise RuntimeError("Android app protection is missing from this APK.")
    version = manifest.get("versionName")
    if not isinstance(version, str) or not version.strip():
        version = build.get("appVersion")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Could not determine this APK's version.")
    if build.get("appVersion") and version != build["appVersion"]:
        raise RuntimeError("APK version does not match the requested EAS build.")
    version_code = manifest.get("versionCode")
    if build.get("appBuildVersion") and str(version_code) != str(build["appBuildVersion"]):
        raise RuntimeError("APK version code does not match the requested EAS build.")
    return {"buildId": BUILD_ID, "version": version, "versionCode": version_code,
            "byteSize": apk.stat().st_size, "sha256": sha256_file(apk),
            "url": DOWNLOAD_URL, "builtAt": build.get("completedAt")}


def get_build(root):
    mobile = root / "mobile"
    if not (mobile / "app.json").is_file():
        raise RuntimeError("Open the original Delimt Codespace containing the mobile folder.")
    prefix = [shutil.which("eas")] if shutil.which("eas") else EAS_PREFIX
    result = run([*prefix, "build:view", BUILD_ID, "--json"], mobile, capture=True)
    build = json.loads(result.stdout)
    owner = build.get("app", {}).get("ownerAccount", {}).get("name")
    if (build.get("id") != BUILD_ID or build.get("status") != "FINISHED"
            or build.get("platform") != "ANDROID" or build.get("appIdentifier") != "com.delimt.app"
            or owner != "delimt" or build.get("app", {}).get("slug") != "delimt-android"):
        raise RuntimeError("The requested build is not a completed Delimt Android build.")
    if str(build.get("buildProfile", "")).lower() in ("development", "dev-client", "development-client"):
        raise RuntimeError("This is a development-client build, not the standalone APK.")
    return build


def download_apk(root, build):
    cache = root.parent / ".delimt-apk-cache" / BUILD_ID
    cache.mkdir(parents=True, exist_ok=True)
    apk = cache / APK_NAME
    receipt = cache / "checksum.json"
    if apk.is_file() and receipt.is_file():
        previous = json.loads(receipt.read_text())
        if previous.get("buildId") == BUILD_ID and previous.get("sha256") == sha256_file(apk):
            print("Reusing the verified cached APK.", flush=True)
            return apk
    url = build.get("artifacts", {}).get("applicationArchiveUrl") or build.get("artifacts", {}).get("buildUrl")
    if not isinstance(url, str) or urlparse(url).scheme != "https":
        raise RuntimeError("EAS did not provide a secure APK download URL.")
    temporary = cache / (APK_NAME + ".part")
    total = 0
    with urlopen(Request(url, headers={"User-Agent": "Delimt-website-updater/1"}), timeout=60) as response, temporary.open("wb") as output:
        expected = int(response.headers.get("Content-Length", "0"))
        if expected > 2 * 1024 ** 3:
            raise RuntimeError("The artifact exceeds the release asset size limit.")
        while True:
            block = response.read(1024 * 1024)
            if not block:
                break
            output.write(block)
            total += len(block)
            if total > 2 * 1024 ** 3:
                raise RuntimeError("The artifact exceeds the release asset size limit.")
            if total // (16 * 1024 * 1024) != (total - len(block)) // (16 * 1024 * 1024):
                print("Downloaded", round(total / 1_000_000), "MB in Codespaces.", flush=True)
        if expected and total != expected:
            raise RuntimeError("The APK download was incomplete. Rerun the updater.")
    with temporary.open("rb") as stream:
        if stream.read(4) != b"PK\x03\x04":
            raise RuntimeError("The download is not an APK archive.")
    os.replace(temporary, apk)
    receipt.write_text(json.dumps({"buildId": BUILD_ID, "sha256": sha256_file(apk)}))
    return apk


def release_info(root, *, required=False):
    result = run(["gh", "api", "repos/" + REPOSITORY + "/releases/tags/" + TAG], root, capture=True, check=False)
    if result.returncode == 0:
        return json.loads(result.stdout)
    if not required and "404" in result.stderr:
        return None
    raise RuntimeError("GitHub could not read the APK release. " + result.stderr.strip())


def verify_asset(root, release, metadata):
    asset = next((a for a in release.get("assets", []) if a.get("name") == APK_NAME), None)
    if not asset:
        return False
    if asset.get("size") != metadata["byteSize"]:
        raise RuntimeError("An existing release asset has different bytes. It was not overwritten.")
    digest = asset.get("digest")
    if digest:
        if digest != "sha256:" + metadata["sha256"]:
            raise RuntimeError("The release asset checksum differs. It was not overwritten.")
    else:
        with tempfile.TemporaryDirectory(prefix="delimt-release-check-") as temp:
            run(["gh", "release", "download", TAG, "--repo", REPOSITORY,
                 "--pattern", APK_NAME, "--dir", temp], root)
            if sha256_file(Path(temp) / APK_NAME) != metadata["sha256"]:
                raise RuntimeError("The release asset checksum differs. It was not overwritten.")
    return True


def public_download_check():
    for attempt in range(2):
        try:
            with urlopen(Request(DOWNLOAD_URL, headers={"Range": "bytes=0-3", "User-Agent": "Delimt-download-check/1"}), timeout=30) as response:
                if response.read(4) != b"PK\x03\x04":
                    raise RuntimeError("The public link does not return an APK.")
            return
        except HTTPError as error:
            if attempt == 0 and error.code == 404:
                time.sleep(2)
                continue
            raise RuntimeError("The APK release is saved, but its anonymous download check failed. Rerun to retry this check.") from error


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prepare-only", action="store_true", help="Write the website files only; no account access, download, commit or publication")
    options = parser.parse_args()
    root = Path(run(["git", "rev-parse", "--show-toplevel"], Path.cwd(), capture=True).stdout.strip())
    remote = run(["git", "remote", "get-url", "origin"], root, capture=True).stdout.strip()
    if not re.fullmatch(r"(?:https://github\.com/|git@github\.com:)activist015/delimt(?:\.git)?/?", remote, re.I):
        raise RuntimeError("Run this from the activist015/delimt Codespace.")
    if not options.prepare_only:
        if not shutil.which("gh"):
            raise RuntimeError("GitHub CLI (gh) is missing from this Codespace.")
        run(["gh", "auth", "status"], root, capture=True)
    print("1/5 Preparing a separate website branch.", flush=True)
    checkout, branch = prepare_worktree(root)
    if options.prepare_only:
        print("Prepared only:", checkout, "\nThe APK download button stays disabled until publication.")
        return
    print("2/5 Reading your existing EAS build and downloading its APK in Codespaces.", flush=True)
    build = get_build(root)
    apk = download_apk(root, build)
    metadata = inspect_apk(apk, build)
    assert valid_config(metadata)
    (checkout / CONFIG_PATH).write_text(json.dumps(metadata, indent=2) + "\n")

    print("3/5 Checking the website tests and production build.", flush=True)
    run(["node", "--test", "tests/android-download.test.js", "tests/profile-referral.test.js"], checkout)
    if not (checkout / "node_modules").exists():
        if ((root / "node_modules").is_dir() and (root / "package-lock.json").read_bytes() == (checkout / "package-lock.json").read_bytes()):
            (checkout / "node_modules").symlink_to(root / "node_modules", target_is_directory=True)
        else:
            run(["npm", "ci", "--no-audit", "--no-fund"], checkout)
    run(["npm", "run", "build"], checkout)

    print("4/5 Publishing this exact APK as an early-access GitHub release.", flush=True)
    release = release_info(root)
    if not release:
        notes = f"""Delimt for Android, early access.

Version: {metadata['version']} (build {metadata['versionCode']})
APK size: {metadata['byteSize']} bytes
SHA-256: {metadata['sha256']}
EAS build: {BUILD_PAGE}

Download delimt-android.apk, install it, then open Apps in Delimt to set up
Android Accessibility protection. The website installation guide will be at
https://www.delimt.com/download after the matching website PR is merged.
AI conversations require an internet connection.

This is the existing tested APK; the website updater does not rebuild or re-sign it.
"""
        with tempfile.NamedTemporaryFile(mode="w", suffix=".md", delete=False) as temp:
            temp.write(notes)
            notes_path = Path(temp.name)
        try:
            target = build.get("gitCommitHash")
            if not isinstance(target, str) or not re.fullmatch(r"[0-9a-f]{40}", target):
                target = "android-foundation"
            else:
                found = run(["gh", "api", "repos/" + REPOSITORY + "/commits/" + target], root, capture=True, check=False)
                if found.returncode:
                    target = "android-foundation"
            run(["gh", "release", "create", TAG, "--repo", REPOSITORY, "--draft", "--prerelease", "--target", target,
                 "--title", "Delimt Android " + metadata["version"] + " (early access)", "--notes-file", str(notes_path)], root)
        finally:
            notes_path.unlink(missing_ok=True)
        release = release_info(root, required=True)
    if not verify_asset(root, release, metadata):
        if not release.get("draft"):
            raise RuntimeError("An existing published release has no matching APK. Nothing was overwritten.")
        run(["gh", "release", "upload", TAG, str(apk), "--repo", REPOSITORY], root)
        release = release_info(root, required=True)
        if not verify_asset(root, release, metadata):
            raise RuntimeError("The APK upload could not be verified.")
    if release.get("draft"):
        run(["gh", "release", "edit", TAG, "--repo", REPOSITORY, "--draft=false", "--prerelease", "--latest=false"], root)
    public_download_check()

    print("5/5 Saving the website branch and opening its review link.", flush=True)
    run(["git", "add", "--", *PAYLOAD.keys()], checkout)
    staged = run(["git", "diff", "--cached", "--name-only"], checkout, capture=True).stdout.splitlines()
    if any(name not in PAYLOAD for name in staged):
        raise RuntimeError("Unexpected staged changes were preserved. No commit was created.")
    if staged:
        run(["git", "commit", "-m", TITLE], checkout)
    run(["git", "push", "-u", "origin", branch], checkout)
    existing = run(["gh", "pr", "view", branch, "--repo", REPOSITORY, "--json", "url", "--jq", ".url"], checkout, capture=True, check=False)
    if existing.returncode == 0:
        pr_url = existing.stdout.strip()
    else:
        body = f"""Make the standalone Android app downloadable from the website.

Adds a public /download page, Android calls to action, device-specific setup
instructions and factual Android permission information. Keeps iPhone and
desktop access through the web app. The APK is hosted in GitHub Releases.

Verified release: {metadata['version']}, {metadata['byteSize']} bytes.
SHA-256: {metadata['sha256']}
Approved EAS build: {BUILD_ID}

Validation: APK package/version/bundled-code/protection checks, GitHub asset
checksum and anonymous download check, 12 website tests, production Vite build.
The download is ready for public access. Merge this PR to deploy its website
links through the existing Vercel setup. This update does not rebuild the APK
or change database permissions, checkout or subscription logic.
"""
        with tempfile.NamedTemporaryFile(mode="w", suffix=".md", delete=False) as temp:
            temp.write(body)
            body_path = Path(temp.name)
        try:
            pr_url = run(["gh", "pr", "create", "--repo", REPOSITORY, "--base", "main", "--head", branch,
                          "--title", TITLE, "--body-file", str(body_path)], checkout, capture=True).stdout.strip()
        finally:
            body_path.unlink(missing_ok=True)
    print("\nAPK published and website update ready.")
    print("Version:", metadata["version"], " | Size:", round(metadata["byteSize"] / 1_000_000, 1), "MB")
    print("APK:", DOWNLOAD_URL)
    print("Website review link:", pr_url)
    print("Merge the website PR after its checks pass. Vercel will deploy /download.")


if __name__ == "__main__":
    try:
        main()
    except (RuntimeError, OSError, ValueError, IndexError, zipfile.BadZipFile, struct.error) as error:
        print("\nUpdate paused:", error, file=sys.stderr)
        print("Your original Android checkout was preserved. No APK build or database migration was run.", file=sys.stderr)
        print("If Expo asks for sign-in, use your existing EAS login in the mobile folder, then rerun this file.", file=sys.stderr)
        sys.exit(1)
